    steps = [("ثبت درخواست","مسئله، هدف و اطلاعات تماس خود را ارسال می‌کنید."),("بررسی نیاز","فرایند فعلی، محدودیت‌ها و نتیجه مورد انتظار بررسی می‌شود."),("انتخاب یا طراحی راهکار","محصول موجود مناسب ارزیابی یا مسیر توسعه اختصاصی تعریف می‌شود."),("پیشنهاد و برآورد","دامنه کار، پیش‌نیازها، زمان و شرایط تحویل شفاف می‌شود."),("پیاده‌سازی و تحویل","راهکار پیکربندی یا توسعه داده و پس از آزمون تحویل می‌شود."),("پشتیبانی و توسعه","مسیر رفع اشکال و افزودن قابلیت‌های بعدی توافق می‌شود.")]
    for index, (title, description) in enumerate(steps, 1):
        if not WorkflowStep.query.filter_by(title=title).first():
            db.session.add(WorkflowStep(title=title, description=description, position=index))

    faqs = [
        ("آیا همه پروژه‌های GitHub محصول آماده فروش هستند؟","خیر. کتابخانه‌ها، زیرساخت‌ها و پروژه‌های ناقص با وضعیت واقعی خود ثبت می‌شوند. فقط محصولات دارای وضعیت «منتشرشده» در سایت عمومی نمایش داده می‌شوند."),
        ("امکان سفارشی‌سازی محصولات وجود دارد؟","بله، پس از بررسی نیاز و ساختار فنی محصول، دامنه سفارشی‌سازی و پیش‌نیازهای آن مشخص می‌شود."),
        ("برای استفاده از محصولات به API یا سرور نیاز دارم؟","بسته به محصول متفاوت است. پیش‌نیازهای سرویس‌های خارجی، مدل هوش مصنوعی و زیرساخت در صفحه هر محصول ذکر شده است."),
        ("هزینه و زمان پیاده‌سازی چگونه مشخص می‌شود؟","پس از ثبت درخواست و روشن‌شدن دامنه کار، پیشنهاد و برآورد جداگانه ارائه می‌شود؛ قیمت یا زمان ساختگی در سایت درج نمی‌شود."),
        ("آیا امکان اتصال به سامانه فعلی ما وجود دارد؟","در صورت وجود API یا مسیر فنی مناسب، امکان یکپارچه‌سازی بررسی می‌شود. جزئیات فنی سامانه فعلی در مرحله تحلیل نیاز لازم است."),
        ("پشتیبانی پس از تحویل چگونه است؟","شرایط رفع اشکال، آموزش و توسعه بعدی در پیشنهاد هر پروژه مشخص و توافق می‌شود."),
    ]
    for index, (question, answer) in enumerate(faqs):
        if not FAQ.query.filter_by(question=question, product_id=None).first():
            db.session.add(FAQ(question=question, answer=answer, position=index))
    from scripts.seed_concepts import seed_concepts
    seed_concepts()
    db.session.commit()
